    from MYLIB.CUSTOMER
   where CUSTOMER_ID = :customerId;

if SQLSTATE = '02000';
  // not found branch
elseif SQLSTATE <> '00000';
  // diagnostic branch
endif;

exec sql
  declare cOrders cursor for
    select ORDER_ID, TOTAL
      from MYLIB.ORDERS
     where CUSTOMER_ID = :customerId
     order by ORDER_ID;
exec sql open cOrders;

