  values (:orderId, :sku, :quantity);

if SQLSTATE = '00000';
  // continue
elseif SQLSTATE = '23505';
  // duplicate business key
else;
  // preserve diagnostic
endif;

exec sql
  select SHIPPED_DATE
    into :shipDate :shipDateNull
    from MYLIB.ORDERS
   where ORDER_ID = :orderId;

if shipDateNull < 0;
  // not scheduled
